BOOK_LEN = 28
TRANSACTION_LEN = 22
INPUT_LEN = 22
MASK64 = (1 << 64) - 1


def read_records(path, record_len):
    with open(path, "rb") as f:
        data = f.read()
    records = []
    for offset in range(0, len(data), record_len):
        record = bytearray(data[offset:offset + record_len])
        if len(record) < record_len:
            record.extend(b"\x00" * (record_len - len(record)))
        records.append(record)
    return records


def write_records(path, records):
    with open(path, "wb") as f:
        for record in records:
            f.write(record)


def parse_display(data, scale):
    size = len(data)
    if size == 0:
        return 0, scale
    if data[0] == 255:
        return 10 ** size, scale
    if data[0] == 0:
        return -(10 ** size), scale

    pos = 0
    remaining = size
    while remaining > 1 and (data[pos] & 0x0F) == 0:
        remaining -= 1
        pos += 1

    value = 0
    for i in range(pos, size):
        if value:
            value = (value * 10) & MASK64
        value = (value + (data[i] - ord("0"))) & MASK64
    return value, scale


def trunc_div(value, divisor):
    quotient = abs(value) // abs(divisor)
    if (value < 0) != (divisor < 0):
        quotient = -quotient
    return quotient


def format_unsigned(value, digits):
    if value == 0:
        return b"0" * digits
    text = str(abs(value))
    if len(text) > digits:
        text = text[-digits:]
    else:
        text = text.zfill(digits)
    return text.encode("ascii")


def amount_work_area(amount_bytes):
    work = bytearray(b"0" * 12)
    for i in range(10):
        byte = amount_bytes[i]
        work[i] = ord("0") if byte in (0x00, 0x20) else byte
    return work


def update_balance(balance_bytes, amount_value, amount_scale, subtract):
    balance_value, balance_scale = parse_display(balance_bytes, 0)
    factor = 10 ** (amount_scale - balance_scale)
    scaled_balance = balance_value * factor
    if subtract:
        result = scaled_balance - amount_value
    else:
        result = scaled_balance + amount_value
    value = trunc_div(result, factor)
    return format_unsigned(value, 10)


