    write_records(accounts_path, accounts)

    for book in books:
        if bytes(book[0:4]) == book_id:
            book[24:28] = buyer_id
    write_records(books_path, books)

    transaction = bytearray(b"0" * TRANSACTION_LEN)
    transaction[0:4] = book_id
